// Lambda: s -> System.out.println(s)
// Method ref: System.out::println    (System.out is a specific PrintStream instance)
trades.forEach(System.out::println);

// More examples:
String prefix = "TRADE-";
.map(prefix::concat)                  // bound: prefix.concat(s) on the specific prefix instance
.filter(pattern::matches)             // bound: regex pattern instance

// ═══ TYPE 3: Unbound instance method — ClassName::instanceMethod ═══
// Lambda: t -> t.getAmount()
// Method ref: Trade::getAmount       (called on each Trade that flows through)
trades.stream().map(Trade::getAmount);

// The FIRST parameter becomes the receiver:
// (Trade t) -> t.getAmount()  ≡  Trade::getAmount
// (String s) -> s.toUpperCase()  ≡  String::toUpperCase
// (String a, String b) -> a.compareTo(b)  ≡  String::compareTo

// More examples:
.map(Trade::getSymbol)                // unbound: each trade calls its own getSymbol()
.map(String::trim)                    // unbound: each string calls its own trim()
.filter(String::isEmpty)              // unbound: each string calls its own isEmpty()
.sorted(String::compareToIgnoreCase)  // unbound: first string calls compareTo on second

