package com.bank.methodref.model;

import java.math.BigDecimal;

public record Trade(String tradeId, String symbol, BigDecimal amount, String status) {
    public boolean isSettled() { return "SETTLED".equals(status); }

    // Static method — for TYPE 1
    public static boolean isValidSymbol(String symbol) {
        return symbol != null && symbol.length() >= 2 && symbol.length() <= 20;
    }

    // Static factory — for TYPE 1
    public static Trade fromCsv(String csv) {
        String[] parts = csv.split(",");
        return new Trade(parts[0], parts[1], new BigDecimal(parts[2]), parts[3]);
    }
}
