// ─── File: src/main/java/com/bank/methodref/service/TradeProcessingService.java ───
package com.bank.methodref.service;

import com.bank.methodref.dto.*;
import com.bank.methodref.model.Trade;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradeProcessingService {

    private final AuditLogger auditLogger;  // specific instance for TYPE 2

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED"),
        new Trade("TRD-002", "TCS", new BigDecimal("176000"), "SETTLED"),
        new Trade("TRD-003", "HDFC", new BigDecimal("330150"), "PENDING"),
        new Trade("TRD-004", "INFY", new BigDecimal("222037"), "SETTLED"),
        new Trade("TRD-005", "", new BigDecimal("0"), "FAILED")
    );

    public MethodRefReport demonstrateAllFourTypes() {
        Map<String, List<String>> examples = new LinkedHashMap<>();
        List<String> steps = new ArrayList<>();

        // ═══ TYPE 1: Static method reference — ClassName::staticMethod ═══
        List<String> validSymbols = trades.stream()
            .map(Trade::symbol)                    // TYPE 3 (see below)
            .filter(Trade::isValidSymbol)          // TYPE 1: static method
            .toList();
        examples.put("TYPE_1_STATIC (Trade::isValidSymbol)", validSymbols);
        steps.add("filter(Trade::isValidSymbol) — static method filters valid symbols");

        // TYPE 1: static factory
        List<Trade> fromCsv = List.of("T6,BAJAJ,153000,SETTLED", "T7,WIPRO,33664,SETTLED")
            .stream()
            .map(Trade::fromCsv)                   // TYPE 1: static factory method
            .toList();
        examples.put("TYPE_1_STATIC_FACTORY (Trade::fromCsv)",
            fromCsv.stream().map(Trade::tradeId).toList());

        // ═══ TYPE 2: Bound instance method — object::instanceMethod ═══
        trades.stream()
            .filter(Trade::isSettled)
            .forEach(auditLogger::logTrade);        // TYPE 2: auditLogger is a specific instance
        examples.put("TYPE_2_BOUND_INSTANCE (auditLogger::logTrade)",
            List.of("Logged 3 settled trades via auditLogger instance"));
        steps.add("forEach(auditLogger::logTrade) — bound to specific AuditLogger instance");

        // TYPE 2: System.out::println
        steps.add("forEach(System.out::println) — bound to System.out PrintStream instance");

        // ═══ TYPE 3: Unbound instance method — ClassName::instanceMethod ═══
        List<String> symbols = trades.stream()
            .map(Trade::symbol)                    // TYPE 3: each Trade calls its own symbol()
            .toList();
        examples.put("TYPE_3_UNBOUND (Trade::symbol)", symbols);

        List<BigDecimal> amounts = trades.stream()
            .map(Trade::amount)                    // TYPE 3: each Trade calls its own amount()
            .toList();
        examples.put("TYPE_3_UNBOUND (Trade::amount)",
            amounts.stream().map(BigDecimal::toPlainString).toList());

        // TYPE 3 with String methods:
        List<String> upperSymbols = symbols.stream()
            .map(String::toUpperCase)              // TYPE 3: each String calls its own toUpperCase()
            .toList();
        steps.add("map(Trade::symbol) + map(String::toUpperCase) — TYPE 3 on each element");

        // ═══ TYPE 4: Constructor reference — ClassName::new ═══
        List<TradeDTO> dtos = trades.stream()
            .filter(Trade::isSettled)
            .map(TradeDTO::new)                    // TYPE 4: new TradeDTO(trade)
            .toList();
        examples.put("TYPE_4_CONSTRUCTOR (TradeDTO::new)",
            dtos.stream().map(TradeDTO::id).toList());
        steps.add("map(TradeDTO::new) — constructor reference creates DTO from each Trade");

        // TYPE 4: collection factory
        TreeSet<String> sortedSymbols = trades.stream()
            .map(Trade::symbol)
            .filter(s -> !s.isEmpty())
            .collect(Collectors.toCollection(TreeSet::new));  // TYPE 4: new TreeSet<>()
        examples.put("TYPE_4_CONSTRUCTOR (TreeSet::new)", List.copyOf(sortedSymbols));

        // ═══ COMPLETE PIPELINE — all four types in one chain ═══
        BigDecimal total = List.of("245050", "176000", "222037").stream()
            .map(BigDecimal::new)                  // TYPE 4: constructor
            .filter(Objects::nonNull)              // TYPE 1: static
            .sorted(Comparator.comparing(BigDecimal::doubleValue))  // TYPE 3: unbound
            .peek(System.out::println)             // TYPE 2: bound instance
            .reduce(BigDecimal.ZERO, BigDecimal::add);  // TYPE 1: static
        steps.add("ALL 4 TYPES in one pipeline: BigDecimal::new → Objects::nonNull → "
            + "BigDecimal::doubleValue → System.out::println → BigDecimal::add = Rs." + total);

        return new MethodRefReport(examples, steps);
    }
}
