// ─── File: src/test/java/com/bank/methodref/service/FourTypesTest.java ───
package com.bank.methodref.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class FourTypesTest {

    // ═══ TYPE 1: Static ═══
    @Test
    void type1_staticMethodReference() {
        // Lambda: s -> Integer.parseInt(s)
        // Method ref: Integer::parseInt
        List<Integer> nums = Stream.of("1", "2", "3").map(Integer::parseInt).toList();
        assertThat(nums).containsExactly(1, 2, 3);
    }

    // ═══ TYPE 2: Bound instance ═══
    @Test
    void type2_boundInstanceMethodReference() {
        StringBuilder sb = new StringBuilder();
        // Lambda: s -> sb.append(s)
        // Method ref: sb::append (bound to specific sb instance)
        Stream.of("A", "B", "C").forEach(sb::append);
        assertThat(sb.toString()).isEqualTo("ABC");
    }

    // ═══ TYPE 3: Unbound instance ═══
    @Test
    void type3_unboundInstanceMethodReference() {
        // Lambda: s -> s.toUpperCase()
        // Method ref: String::toUpperCase (called on each element)
        List<String> upper = Stream.of("reliance", "tcs").map(String::toUpperCase).toList();
        assertThat(upper).containsExactly("RELIANCE", "TCS");
    }

    @Test
    void type3_comparator() {
        // Lambda: (a, b) -> a.compareToIgnoreCase(b)
        // Method ref: String::compareToIgnoreCase
        List<String> sorted = Stream.of("TCS", "hdfc", "Reliance")
            .sorted(String::compareToIgnoreCase).toList();
        assertThat(sorted).containsExactly("hdfc", "Reliance", "TCS");
    }

    // ═══ TYPE 4: Constructor ═══
    @Test
    void type4_constructorReference() {
        // Lambda: s -> new BigDecimal(s)
        // Method ref: BigDecimal::new
        List<BigDecimal> amounts = Stream.of("100", "200").map(BigDecimal::new).toList();
        assertThat(amounts).containsExactly(new BigDecimal("100"), new BigDecimal("200"));
    }

    @Test
    void type4_supplierConstructor() {
        // Lambda: () -> new ArrayList<>()
        // Method ref: ArrayList::new
        Supplier<List<String>> factory = ArrayList::new;
        List<String> list = factory.get();
        list.add("RELIANCE");
        assertThat(list).containsExactly("RELIANCE");
    }

    // ═══ All four in one pipeline ═══
    @Test
    void allFourTypesInOnePipeline() {
        StringBuilder log = new StringBuilder();

        List<Integer> result = Stream.of("3", "1", "2")
            .map(Integer::parseInt)                    // TYPE 1: static
            .sorted(Integer::compareTo)                // TYPE 3: unbound
            .peek(log::append)                         // TYPE 2: bound to log instance
            .collect(Collectors.toCollection(ArrayList::new));  // TYPE 4: constructor

        assertThat(result).containsExactly(1, 2, 3);
        assertThat(log.toString()).isEqualTo("123");
    }
}
